import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    // 简单固定窗口限流器，模拟 RequestRateLimiter
    static final class FixedWindowLimiter {
        private final int capacity;
        private final Map<String, Integer> counts = new HashMap<>();
        FixedWindowLimiter(int capacity) { this.capacity = capacity; }
        synchronized boolean allow(String key) {
            int used = counts.getOrDefault(key, 0);
            if (used >= capacity) return false;
            counts.put(key, used + 1);
            return true;
        }
    }

    static final AtomicInteger REQUEST_ID = new AtomicInteger();

    public static void main(String[] args) throws Exception {
        // 模拟后端服务
        HttpServer backend = HttpServer.create(new InetSocketAddress(0), 0);
        backend.createContext("/orders/42", exchange -> {
            String rid = exchange.getRequestHeaders().getFirst("X-Request-Id");
            respond(exchange, 200, "backend rid=" + rid);
        });
        backend.start();

        FixedWindowLimiter limiter = new FixedWindowLimiter(2);
        HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();
        HttpServer gateway = HttpServer.create(new InetSocketAddress(0), 0);
        int backendPort = backend.getAddress().getPort();
        gateway.createContext("/", exchange -> {
            try {
                handleGateway(exchange, backendPort, limiter, client);
            } catch (Exception e) {
                respond(exchange, 502, "gateway error=" + e.getClass().getSimpleName());
            }
        });
        gateway.start();

        int gwPort = gateway.getAddress().getPort();
        // 1. 路由不匹配 → 404
        System.out.println(call(gwPort, "/missing", null));
        // 2. 无鉴权 → 401
        System.out.println(call(gwPort, "/api/orders/42", null));
        // 3. 正常请求 → 200
        System.out.println(call(gwPort, "/api/orders/42", "Bearer tok"));
        // 4. 第二次正常
        System.out.println(call(gwPort, "/api/orders/42", "Bearer tok"));
        // 5. 第三次限流 → 429
        System.out.println(call(gwPort, "/api/orders/42", "Bearer tok"));

        gateway.stop(0);
        backend.stop(0);
    }

    static void handleGateway(com.sun.net.httpserver.HttpExchange ex, int backendPort,
                              FixedWindowLimiter limiter, HttpClient client) throws Exception {
        String path = ex.getRequestURI().getPath();
        // --- Predicate 匹配：只匹配 /api/** ---
        if (!path.startsWith("/api/")) {
            respond(ex, 404, "no route matched");
            return;
        }
        // --- pre filter 1: 鉴权 ---
        String auth = ex.getRequestHeaders().getFirst("Authorization");
        if (auth == null || auth.isBlank()) {
            respond(ex, 401, "unauthorized");
            return;
        }
        // --- pre filter 2: 限流 ---
        if (!limiter.allow(auth)) {
            respond(ex, 429, "rate limited key=" + auth);
            return;
        }
        // --- pre filter 3: StripPrefix + Header 注入 ---
        String rewrittenPath = path.substring("/api".length());
        String reqId = "gw-" + REQUEST_ID.incrementAndGet();
        HttpRequest req = HttpRequest.newBuilder()
                .uri(URI.create("http://127.0.0.1:" + backendPort + rewrittenPath))
                .timeout(Duration.ofSeconds(2))
                .header("Authorization", auth)
                .header("X-Request-Id", reqId)
                .GET().build();
        // --- 转发到后端 ---
        HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.ofString());
        // --- post filter: 加响应头 ---
        ex.getResponseHeaders().add("X-Gateway-RouteId", "orders");
        respond(ex, resp.statusCode(), "route=orders, " + resp.body());
    }

    static String call(int port, String path, String auth) throws Exception {
        var b = HttpRequest.newBuilder()
                .uri(URI.create("http://127.0.0.1:" + port + path))
                .timeout(Duration.ofSeconds(2)).GET();
        if (auth != null) b.header("Authorization", auth);
        var r = HttpClient.newHttpClient().send(b.build(), HttpResponse.BodyHandlers.ofString());
        return r.statusCode() + " " + r.body();
    }

    static void respond(com.sun.net.httpserver.HttpExchange ex, int status, String body) throws IOException {
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        ex.sendResponseHeaders(status, bytes.length);
        try (OutputStream out = ex.getResponseBody()) { out.write(bytes); }
    }
}
